// === Tab: mySketch ===
const NUM = 15;
const SZE = 250;
let triangles;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	colorMode(HSB);

	const HUE_OFFSET = random(360);
	const HUE_RANGE = random(30, 180);
	triangles = [];
	for (let i = 0; i < NUM; i++) {
		const NUM_PIECES = random(3, 7)
		const clr = {h: HUE_OFFSET + random(HUE_RANGE) + (180 * ((random() < 0.1) ? 1 : 0)), s: random(50, 75), b: random(35, 65)}
		const points = [];
		for (let j = 0; j < NUM_PIECES; j++) {
			const x = random(-SZE, SZE);
			const y = random(-SZE, SZE);
			const z = random(-SZE, SZE);
			points.push({x, y, z})
		}
		triangles.push({clr, points});
	}
}

function draw() {
	background(0);
	orbitControl();

	rotateY(frameCount * 0.0081)
	rotateZ(frameCount * 0.0031)

	lights();

	fill(255, 64)
	stroke("white")
	noStroke();
	for (let t of triangles) {
		var clr = t.clr;
		const pts = t.points;
		fill(clr.h, clr.s, clr.b, 0.25); // +frameCount
		beginShape(TRIANGLE_STRIP);
		for (let p of pts) {
			vertex(p.x, p.y, p.z)
		}
		endShape(CLOSE);
	}
}

function doubleClicked() {
	if (mouseButton === LEFT) {
		setup();
		return false;		// prevent default
	}
}
